//! Writes `CLAUDE.md` and `AGENTS.md` into a project's directory from the `claude.md` of its
//! memory zone, so the project stays usable without kindric. A generated file starts with a mark
//! holding the fingerprint of its body: anything without a matching mark is never overwritten.

use std::fs;
use std::io;
use std::path::Path;

use crate::shared::fingerprint;

use crate::memory::Memory;

const TARGETS: [&str; 2] = ["CLAUDE.md", "AGENTS.md"];
const MARK_START: &str = "<!-- Generated by kindric. Edit the source in kindric, not this file. fingerprint: ";
const MARK_END: &str = " -->";
const HEADER_FENCE: &str = "---";

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Outcome {
    Written,
    Unchanged,
    /// A generated file whose body no longer matches its mark: left as it is.
    EditedByHand,
    /// A file kindric did not write, or a link: left as it is.
    NotOurs,
    /// Nothing to generate from: left as it is.
    EmptySource,
}

/// What `directory` should hold for this source, or `None` if the source has no body.
pub fn render(source: &str) -> io::Result<Option<String>> {
    let source = source.replace("\r\n", "\n");
    let body = without_header(&source)?.trim();
    if body.is_empty() {
        return Ok(None);
    }
    let body = format!("{body}\n");
    Ok(Some(format!("{MARK_START}{}{MARK_END}\n{body}", fingerprint(body.as_bytes()))))
}

/// The header holds the project's access to the rest of the memory, and generated files can end
/// up in a public repository: a header that is not closed is an error, never copied as text.
fn without_header(source: &str) -> io::Result<&str> {
    let Some(after_opening) = source.strip_prefix(HEADER_FENCE).and_then(|rest| rest.strip_prefix('\n')) else {
        return Ok(source);
    };
    let mut position = 0;
    for line in after_opening.split_inclusive('\n') {
        position += line.len();
        if line.trim_end_matches('\n') == HEADER_FENCE {
            return Ok(&after_opening[position..]);
        }
    }
    Err(io::Error::new(io::ErrorKind::InvalidData, "claude.md: the header is not closed by a --- line"))
}

/// Generates both files; a file left as it is does not stop the other one.
pub fn write_instructions(memory: &Memory, project: &str, directory: &Path) -> io::Result<Vec<(&'static str, Outcome)>> {
    let Some(rendered) = render(&memory.instructions_source(project)?)? else {
        return Ok(TARGETS.map(|name| (name, Outcome::EmptySource)).to_vec());
    };
    let mut outcomes = Vec::with_capacity(TARGETS.len());
    for name in TARGETS {
        outcomes.push((name, write_target(&directory.join(name), &rendered)?));
    }
    Ok(outcomes)
}

fn write_target(path: &Path, rendered: &str) -> io::Result<Outcome> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if !metadata.is_file() => return Ok(Outcome::NotOurs),
        Ok(_) => {}
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            write_atomic(path, rendered)?;
            return Ok(Outcome::Written);
        }
        Err(error) => return Err(error),
    }
    let existing = match fs::read_to_string(path) {
        Ok(text) => text.replace("\r\n", "\n"),
        Err(error) if error.kind() == io::ErrorKind::InvalidData => return Ok(Outcome::NotOurs),
        Err(error) => return Err(error),
    };
    if let Some(left_as_is) = refusal(&existing) {
        return Ok(left_as_is);
    }
    if existing == rendered {
        return Ok(Outcome::Unchanged);
    }
    write_atomic(path, rendered)?;
    Ok(Outcome::Written)
}

/// Why `existing`, with Unix line endings, must not be overwritten.
fn refusal(existing: &str) -> Option<Outcome> {
    let (mark, body) = existing.split_once('\n').unwrap_or((existing, ""));
    let Some(recorded) = mark.strip_prefix(MARK_START).and_then(|rest| rest.strip_suffix(MARK_END)) else {
        return Some(Outcome::NotOurs);
    };
    (recorded != fingerprint(body.as_bytes())).then_some(Outcome::EditedByHand)
}

/// A reader never sees half a file. Normal permissions: these files live in the project.
fn write_atomic(path: &Path, content: &str) -> io::Result<()> {
    let name = path.file_name().map(|name| name.to_string_lossy().into_owned()).unwrap_or_default();
    let temporary = path.with_file_name(format!(".{name}.{}.tmp", std::process::id()));
    let written = fs::write(&temporary, content).and_then(|()| fs::rename(&temporary, path));
    if written.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    written
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;

    const SOURCE: &str = "---\naccess: perso\n---\n# Rules\n\nBe direct.\n";

    /// A memory holding `source` as the `claude.md` of project `p`, and an empty project directory.
    fn setup(label: &str, source: &str) -> (PathBuf, Memory, PathBuf) {
        let root = std::env::temp_dir().join(format!("kindric-generate-{label}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        let memory = Memory::at(root.join("memory"));
        memory.ensure_project("p").unwrap();
        fs::write(root.join("memory/projets/p/claude.md"), source).unwrap();
        let project = root.join("project");
        fs::create_dir_all(&project).unwrap();
        (root, memory, project)
    }

    fn outcomes(memory: &Memory, project: &Path) -> Vec<(&'static str, Outcome)> {
        write_instructions(memory, "p", project).unwrap()
    }

    fn both(outcome: Outcome) -> Vec<(&'static str, Outcome)> {
        vec![("CLAUDE.md", outcome), ("AGENTS.md", outcome)]
    }

    #[test]
    fn the_header_is_never_copied() {
        let rendered = render(SOURCE).unwrap().unwrap();
        assert!(!rendered.contains("access"));
        assert!(rendered.ends_with("\n# Rules\n\nBe direct.\n"));
        assert!(rendered.starts_with(MARK_START));
    }

    #[test]
    fn a_fence_further_down_is_ordinary_text() {
        let rendered = render("# Title\n---\nnot a header\n---\nend\n").unwrap().unwrap();
        assert!(rendered.contains("# Title\n---\nnot a header\n---\nend\n"));
        let after_header = render("---\na: b\n---\ntext\n---\nmore\n").unwrap().unwrap();
        assert!(after_header.ends_with("\ntext\n---\nmore\n"));
    }

    #[test]
    fn a_header_that_is_not_closed_is_an_error_and_writes_nothing() {
        let (root, memory, project) = setup("open-header", "---\naccess: perso\nbody\n");
        let error = write_instructions(&memory, "p", &project).unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        assert_eq!(fs::read_dir(&project).unwrap().count(), 0);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_source_with_a_header_only_is_empty() {
        assert_eq!(render("---\naccess: perso\n---\n \n").unwrap(), None);
    }

    #[test]
    fn missing_files_are_written_with_the_same_content() {
        let (root, memory, project) = setup("written", SOURCE);
        assert_eq!(outcomes(&memory, &project), both(Outcome::Written));
        let claude = fs::read_to_string(project.join("CLAUDE.md")).unwrap();
        assert_eq!(claude, render(SOURCE).unwrap().unwrap());
        assert_eq!(claude, fs::read_to_string(project.join("AGENTS.md")).unwrap());
        assert_eq!(fs::read_dir(&project).unwrap().count(), 2);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn an_intact_file_is_updated_when_the_source_changes() {
        let (root, memory, project) = setup("update", SOURCE);
        outcomes(&memory, &project);
        fs::write(root.join("memory/projets/p/claude.md"), "New rules.\n").unwrap();
        assert_eq!(outcomes(&memory, &project), both(Outcome::Written));
        assert!(fs::read_to_string(project.join("CLAUDE.md")).unwrap().ends_with("\nNew rules.\n"));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn an_up_to_date_file_is_left_alone() {
        let (root, memory, project) = setup("unchanged", SOURCE);
        outcomes(&memory, &project);
        assert_eq!(outcomes(&memory, &project), both(Outcome::Unchanged));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_file_edited_by_hand_keeps_its_content() {
        let (root, memory, project) = setup("by-hand", SOURCE);
        outcomes(&memory, &project);
        let file = project.join("CLAUDE.md");
        let edited = fs::read_to_string(&file).unwrap() + "my own line\n";
        fs::write(&file, &edited).unwrap();
        fs::write(root.join("memory/projets/p/claude.md"), "New rules.\n").unwrap();
        let result = outcomes(&memory, &project);
        assert_eq!(result[0], ("CLAUDE.md", Outcome::EditedByHand));
        assert_eq!(fs::read_to_string(&file).unwrap(), edited);
        assert_eq!(result[1], ("AGENTS.md", Outcome::Written), "a refusal does not stop the other file");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_file_without_the_mark_is_not_ours() {
        let (root, memory, project) = setup("not-ours", SOURCE);
        let file = project.join("AGENTS.md");
        fs::write(&file, "# written by someone\n").unwrap();
        let result = outcomes(&memory, &project);
        assert_eq!(result[1], ("AGENTS.md", Outcome::NotOurs));
        assert_eq!(fs::read_to_string(&file).unwrap(), "# written by someone\n");
        assert_eq!(result[0], ("CLAUDE.md", Outcome::Written), "a refusal does not stop the other file");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_file_that_is_not_text_is_not_ours() {
        let (root, memory, project) = setup("binary", SOURCE);
        let file = project.join("CLAUDE.md");
        fs::write(&file, [0xff, 0xfe, 0x00]).unwrap();
        assert_eq!(outcomes(&memory, &project)[0], ("CLAUDE.md", Outcome::NotOurs));
        assert_eq!(fs::read(&file).unwrap(), [0xff, 0xfe, 0x00]);
        fs::remove_dir_all(root).unwrap();
    }

    #[cfg(unix)]
    #[test]
    fn a_link_is_not_ours_and_keeps_pointing_where_it_did() {
        let (root, memory, project) = setup("link", SOURCE);
        let target = root.join("elsewhere.md");
        fs::write(&target, render(SOURCE).unwrap().unwrap()).unwrap();
        std::os::unix::fs::symlink(&target, project.join("CLAUDE.md")).unwrap();
        assert_eq!(outcomes(&memory, &project)[0], ("CLAUDE.md", Outcome::NotOurs));
        assert_eq!(fs::read_link(project.join("CLAUDE.md")).unwrap(), target);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn an_empty_source_writes_nothing_and_keeps_what_is_there() {
        let (root, memory, project) = setup("empty", SOURCE);
        outcomes(&memory, &project);
        let before = fs::read_to_string(project.join("CLAUDE.md")).unwrap();
        fs::write(root.join("memory/projets/p/claude.md"), "\n").unwrap();
        assert_eq!(outcomes(&memory, &project), both(Outcome::EmptySource));
        assert_eq!(fs::read_to_string(project.join("CLAUDE.md")).unwrap(), before);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_missing_source_is_an_empty_one() {
        let (root, memory, project) = setup("missing", SOURCE);
        fs::remove_file(root.join("memory/projets/p/claude.md")).unwrap();
        assert_eq!(outcomes(&memory, &project), both(Outcome::EmptySource));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn line_endings_converted_by_git_are_not_an_edit() {
        let (root, memory, project) = setup("crlf", SOURCE);
        outcomes(&memory, &project);
        let file = project.join("CLAUDE.md");
        let converted = fs::read_to_string(&file).unwrap().replace('\n', "\r\n");
        fs::write(&file, &converted).unwrap();
        assert_eq!(outcomes(&memory, &project)[0], ("CLAUDE.md", Outcome::Unchanged));
        fs::write(root.join("memory/projets/p/claude.md"), "New rules.\r\n").unwrap();
        assert_eq!(outcomes(&memory, &project)[0], ("CLAUDE.md", Outcome::Written));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_source_with_windows_line_endings_loses_its_header_too() {
        let rendered = render("---\r\naccess: perso\r\n---\r\ntext\r\n").unwrap().unwrap();
        assert!(!rendered.contains("access"));
        assert!(rendered.ends_with("\ntext\n"));
    }

    #[test]
    fn an_invalid_project_name_is_refused() {
        let (root, memory, project) = setup("name", SOURCE);
        let error = write_instructions(&memory, "../x", &project).unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::InvalidInput);
        assert_eq!(fs::read_dir(&project).unwrap().count(), 0);
        fs::remove_dir_all(root).unwrap();
    }
}
